\begin{theorem}\label{thm:strg_cvx_rate}%
Let $f \in \mathcal{F}_{\mu, L}$, with $\mu \in (0, L)$, and consider $N$ iterations of \eqref{eq:GM_it_fixed_steps} with stepsizes $\gamma L \in (0, 2)$ starting from $x_0$. Then the following bound holds:%
\begin{align}\label{eq:strg_cvx_full_ct}
\begin{aligned}
    \frac{1}{2L} \|\nabla f(x_N)\|^2
        {} \leq {}  
    \frac{f(x_0)-f_*}
    { 1 + \gamma L \min \big\{
    \frac{-1+(1-\gamma \mu)^{-2N}}{\gamma \mu}
    \,,\,
    \frac{-1+(1-\gamma L)^{-2N}}{\gamma L}
         \big\}}.
\end{aligned}
\end{align}%
\end{theorem}

