\begin{theorem}[Interpolation conditions for smooth functions]\label{thm:interp_hypo}
Set $\mathcal{T}=\big\{(x_i, g_i, f_i)\big\}_{i \in \mathcal{I}}$ is $\mathcal{F}_{\mu,L}$-interpolable, where $\mu \in (-\infty, L)$, if and only if for every pair of indices $(i,j)$, with $i,j \in \mathcal{I}$, it holds:%
\begin{align}\label{eq:Interp_hypoconvex}
f_{i}{-}f_{j}{-}\langle g_{j}, x_{i}-x_{j} \rangle 
        {}\geq{}
    \frac{1}{2L} \|g_{i}{-}g_{j}\|^{2} {}+{} \frac{\mu}{2L(L{-}\mu)} \|g_{i}{-}g_{j} {-} L (x_i {-}x_j)\|^2.
\end{align}%
\end{theorem}

\begin{corollary} \label{corr:direct_sum_interp_cond} 
Let $f \in \mathcal{F}_{\mu,L}$, with $\mu \in (-\infty, L)$. For all $x_i, x_j \in \mathbb{R}^d$ it holds:%
\begin{align}\label{eq:direct_sum_interp_cond}
    0 {}\geq{} \left\langle \nabla f(x_i) - \nabla f(x_j) - L(x_i-x_j) \,,\, 
                           \nabla f(x_i) - \nabla f(x_j) - \mu(x_i-x_j) \right\rangle.
\end{align}%
\end{corollary}

\begin{proof}
    Inequality \eqref{eq:direct_sum_interp_cond} results by summing up inequalities \eqref{eq:Interp_hypoconvex} written for the pairs $(x_i,x_j)$ and $(x_j,x_i)$ and performing simplifications.
\qed\end{proof}

\begin{lemma}\label{lemma:sufficient_decrease_N_*}
Let $f \in \mathcal{F}_{\mu,L}$, with $\mu \in (-\infty, L)$. One iteration of \eqref{eq:GM_it_fixed_steps} with stepsize $\gamma L \in (0,2)$ decreases the function values and at each point $x_i$ it holds:
\begin{align}\label{eq:sufficient_decrease_N_*}
    f(x_i) - f_* {}\geq{} \frac{1}{2L} \|\nabla f(x_i)\|^2.
\end{align}%
\end{lemma}

\begin{proposition}[General procedure]\label{prop:general_procedure_min_grad_nrm}
    Inequality \eqref{eq:I^k_N_general_ineq} implies:
\[
    \frac{f(x_0) - f(x_N)}{\sum_{i=0}^N \sigma_i}
        {}\geq{}
    \frac{1}{2L} \,
    \min_{0\leq i \leq N} \big\{\|\nabla f(x_i)\|^2\big\},
\]
with equality only if all gradient norms $\|\nabla f(x_i)\|^2$ with $\sigma_i>0$ are equal. Moreover, 
\[
    \frac{f(x_0) - f_*}{1 + \sum_{i=0}^N \sigma_i}
        {}\geq{}
    \frac{1}{2L} \,
    \min_{0\leq i \leq N} \big\{\|\nabla f(x_i)\|^2\big\}.
\]
\end{proposition}

\begin{proof}
   The first inequality results after taking minimum gradient norm in \eqref{eq:I^k_N_general_ineq}. %
The adjustment in the denominator of the second inequality results from combining \eqref{eq:sufficient_decrease_N_*} with \eqref{eq:I^k_N_general_ineq} and taking again the minimum gradient norm. \qed
\end{proof}

\begin{lemma}\label{lemma:sufficient_decrease_h_leq_1}
    Let $f \in \mathcal{F}_{\mu,L}$, with $\mu \in (-\infty, L)$, and consider one iteration of \eqref{eq:GM_it_fixed_steps} with stepsize $\gamma L \in(0,1]$. Then the following inequality holds, with equality only if $\nabla f(x_{i}) = \nabla f(x_{i+1})$ or $\gamma L = 1$:
\begin{align}\label{eq:one_step_rate_h_leq_1} \tag{N2SD}
\hspace{-.5em}
    f(x_{i}) {-} f(x_{i+1})
        {}\geq {}
    \frac{\gamma L \, \gamma \mu {-} 2\gamma \mu {+} \gamma L}{L{-}\mu} \frac{\|\nabla f(x_{i})\|^2}{2} +
    \frac{\gamma L}{L{-}\mu} \frac{\|\nabla f(x_{i+1})\|^{2}}{2}.
\end{align}%
    Furthermore, if $\mu \leq 0$, then the gradient norms from \eqref{eq:one_step_rate_h_leq_1} are weighted by positive quantities.
\end{lemma}

\begin{proof}\label{proof:lemma:sufficient_decrease_h_leq_1}
    Inequality \eqref{eq:hypo_interp_(0,1)} is reformulated by expressing the inner product in terms of gradient norms, i.e., $2 \big\langle g_{i}, g_{i+1}\big\rangle = \|g_{i}\|^2 + \|g_{i+1}\|^2 - \|g_{i} - g_{i+1}\|^2$, as:%
\begin{align} \label{eq:tight_short_step_sizes}
    f_{i}{-}f_{i+1}
        {}\geq {}
    \frac{\gamma L \, \gamma \mu {-} 2\gamma \mu {+} \gamma L}{L{-}\mu} \frac{\|g_{i}\|^2}{2} +
    \frac{\gamma L}{L{-}\mu} \frac{\|g_{i+1}\|^{2}}{2} +
    \frac{1 {-} \gamma L}{L{-}\mu} \frac{\|g_{i} {-} g_{i+1}\|^{2}}{2}.
\end{align}
Since $\gamma L \in (0,1]$, the mixed term can be neglected, resulting in inequality \eqref{eq:one_step_rate_h_leq_1}, with equality only if $g_{i} = g_{i+1}$ or $\gamma L = 1$. The numerator of first term rewrites as $-\gamma \mu(1-\gamma L) + (\gamma L - \gamma \mu)$, hence it is positive when $\mu \leq 0$.
\qed\end{proof}

\begin{lemma}\label{lemma:sufficient_decrease_h_geq_1}
    Let $f \in \mathcal{F}_{\mu,L}$, with, $\mu \in (-\infty,L)$, and consider one iteration of \eqref{eq:GM_it_fixed_steps} with stepsize $\gamma L \in [1,\gbari[\infty])$. Then the following inequality holds:%
\begin{align} \label{eq:one_step_rate_h_geq_1} \tag{N4SD}
% \hspace{-.25em}
    f(x_{i}){-}f(x_{i+1})
        {}\geq {}
    \frac{\gamma [(2{-}\gamma L)(2{-}\gamma \mu){-}1]}{2{-}\gamma L {- }\gamma \mu}
    \frac{\|\nabla f(x_{i})\|^2}{2} +
    \frac{\gamma}{2{-}\gamma L {-} \gamma \mu} \frac{\|\nabla f(x_{i+1})\|^{2}}{2}.
\end{align}%
When $\gamma L > 1$, equality holds only if:%
\begin{align}\label{eq:equality_case_h_geq_1}
    {\langle \nabla f(x_{i})}, {\nabla f(x_{i+1})\rangle}
        {}{=}{} 
    \frac{(1{-}\gamma \mu)(1{-}\gamma L)}{2{-}\gamma L{-}\gamma \mu} \|\nabla f(x_{i})\|^2 {}{+}{} 
    \frac{1}{2{-}\gamma L{-}\gamma \mu} \|\nabla f(x_{i+1})\|^2.%
\end{align}%
Furthermore, if $\gamma L \in [1,\gbari[1]]$, then the gradient norms from \eqref{eq:one_step_rate_h_geq_1} are weighted by nonnegative quantities.%
\end{lemma}

\begin{proof}\label{proof:lemma:sufficient_decrease_h_geq_1}
The mixed term in inequality \eqref{eq:tight_short_step_sizes} enters with a negative contribution for $\gamma L > 1$. To counterbalance it, the complementary interpolation inequality \eqref{eq:hypo_interp_(1,0)} is used, written with the equivalent expression:%
\begin{align*}
   f_{i+1}-f_{i}
        {}\geq {}
    \frac{\gamma L \gamma \mu {-} 2 \gamma L {+} \gamma \mu}{L{-}\mu} \frac{\|g_{i}\|^2}{2} +
    \frac{\gamma \mu}{L{-}\mu} \frac{\|g_{i+1}\|^{2}}{2} +
    \frac{1 {-} \gamma \mu}{L{-}\mu} \frac{\|g_{i} {-} g_{i+1}\|^{2}}{2}.%
\end{align*}%
Consider the sum of distance-1 inequalities $\bar{I}_{i}^{1} {}\coloneqq{} \Iij[i][i+1] + \Iji[i][i+1]$:%
\begin{align}\label{eq:dist_1_blended_mixed_grads_diff} \tag{$\bar{I}_{i}^{1}$}
\hspace{-0.5em}
0
    {}\geq{}
\frac{2 \gamma L \gamma \mu {-} \gamma L {-} \gamma \mu}{L{-}\mu} \frac{\|g_{i}\|^2}{2} {}+{}
\frac{\gamma L {+} \gamma \mu}{L{-}\mu} \frac{\|g_{i+1}\|^2}{2} {}+{} 
\frac{2{-}\gamma L {-} \gamma \mu}{L{-}\mu} \frac{\| g_{i} {-} g_{i+1}\|^2}{2}.
\end{align}%
By weighting \eqref{eq:dist_1_blended_mixed_grads_diff} with $\beta(\gamma L,\gamma \mu){}\coloneqq{} \tfrac{\gamma L{-}1}{2{-}\gamma L {-}\gamma \mu} \geq 0$ and summing it with \eqref{eq:tight_short_step_sizes}, the coefficient of $\| g_{i} {-} g_{i+1}\|^2$ gets canceled and we obtain \eqref{eq:one_step_rate_h_geq_1}.
The equality condition \eqref{eq:equality_case_h_geq_1} follows from the equality case of \eqref{eq:dist_1_blended_mixed_grads_diff}. Nevertheless, the coefficient of $\|g_{i}\|^2$ is nonnegative for $\gamma L \in [1,\gbari[1]]$, where $\gbari[1]$ is the largest stepsize $\gamma L \in [1, 2)$ for which $(2-\gamma L)(2-\gamma \mu) - 1 \geq {} 0$, implying nonnegativity of the weight of $\|\nabla f(x_{i})\|^2$ in \eqref{eq:one_step_rate_h_geq_1}.\qed
\end{proof}

\begin{proposition}\label{prop:properties:m+n>0}%[Properties for distance-2]
    Let $\mu \in (-\infty, L)$ and $\gamma L \in \big(1, \gbari[\infty] \big)$. Then $\m {}>{}  0$, $\m + \n {}>0$ and $\n^{-2} {}>{} \m^{-2}$.
\end{proposition}

\begin{lemma}\label{lemma:dist_1_L_1_step_decrease}
Let $f \in \mathcal{F}_{\mu,L}$, with $\mu \in (-\infty,L)$, and consider one iteration of \eqref{eq:GM_it_fixed_steps} from $x_i$ with stepsize $\gamma L \in (1, 2)$. Then it holds:
\begin{align} \label{eq:dist_1_L_1_step_decrease} 
    \begin{aligned}    
    \frac{f(x_{i}) - f(x_{i+1})}{\gamma} 
                {}\geq{}
            {-}\Ei[i][\n] \frac{\|\nabla f(x_{i})\|^2}{2} {}+{}
            \Ei[i+1][\n] \frac{\|\nabla f(x_{i+1})\|^2}{2} {}+{}            
            \\ {}+{}
            \frac{ 1 - (\m+\n) \Ei[i+1][\n] }{\m-\n} \frac{\|\nabla f(x_{i+1})-\n \nabla f(x_{i})\|^2}{2}.
    \end{aligned}
\end{align}%
Furthermore, if $\mu \in (0,L)$ and $\gamma L \in [\frac{2}{1+\kappa}, 2)$, then $1-(\m+\n) \Ei[i][\n] > 0$.
\end{lemma}

\begin{proof}
Let $\beta_{i+1}(\n) {{}{}\coloneqq{}{}} (-\n) \Ei[i+1][\n] {}>{} 0$. Inequality \eqref{eq:dist_1_L_1_step_decrease} results after performing the simplifications in the linear combination of interpolation inequalities:
$$
\Iij[i][i+1] + \beta_{i+1}(\n) \, (\Iij[i][i+1] + \Iji[i][i+1]),$$
where \eqref{eq:distance-N_interpolation_conditions_I_ij} and \eqref{eq:distance-N_interpolation_conditions_I_ji} are equivalently rewritten for the pair $(i,i+1)$ as:%
$$
    \begin{aligned}
    (1+\beta_{i+1}) {\,} \Iij[i][i+1] {}:{}
        \frac{f_{i} {-} f_{i+1}}{\gamma}
            {}\geq{}&
        (1+\n) \frac{\|g_{i}\|^2}{2} {+} \frac{1}{\m{-}\n} \frac{\|g_{i+1}{-}\n g_{i}\|^2}{2}; \\
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \beta_{i+1} {\,} \Iji[i][i+1] {}:{}
        \frac{f_{i+1} {-} f_{i}}{\gamma}
            {}\geq{}&
        {-}\frac{\|g_{i}\|^2}{2} {-} \frac{1}{\n} \frac{\|g_{i+1}\|^2}{2} {+} \frac{\m}{\n} \frac{1}{\m{-}\n} \frac{\|g_{i+1}{-}\n g_{i}\|^2}{2}.
    \end{aligned}
$$%
\noindent{}With $\gamma L \in {[}\frac{2}{1+\kappa}, 2)$, we have $\m{+}\n \leq 0$ (see \cref{prop:properties:m+n>0}) and therefore $1-(\m+\n)\Ei[i+1][\n] > 0$.%
\qed \end{proof}

\begin{lemma}\label{lemma:dist_1_mu_1_step_decrease}
Let $f \in \mathcal{F}_{\mu,L}$, with $\mu \in (-\infty,L)$, and consider one iteration of \eqref{eq:GM_it_fixed_steps} from $x_i$ with stepsize $\gamma L \in \big(0, \gbari[\infty]\big)$. Then it holds:%
\begin{align} \label{eq:dist_1_mu_1_step_decrease}
    \begin{aligned}    
    \frac{f(x_{i}) - f(x_{i+1})}{\gamma} 
                {}\geq{} 
            -\Ei[i][\m] \frac{\|\nabla f(x_{i})\|^2}{2} {}+{}
             \Ei[i+1][\m] \frac{\|\nabla f(x_{i+1})\|^2}{2} {}+{}            
            \\ {}+{}
            \frac{{-1} +(\m+\n) \Ei[i+1][\m]}{\m-\n} \frac{\|\nabla f(x_{i+1})-\m \nabla f(x_{i})\|^2}{2}.
    \end{aligned}
\end{align}%
Furthermore, if $\mu \in (0,L)$ and $\gamma L \in \big(0, \gbari[i+1]\big)$, then ${-1} +(\m+\n) \Ei[i+1][\m] > 0$.%
\end{lemma}

\begin{proof}%
Firstly, note that $\m=1-\gamma \mu > 0$; the case $\gamma L \in \big(1, \frac{2}{1+[\kappa]_{+}}\big)$ is covered by \cref{prop:properties:m+n>0}, while for $\gamma L \in (0,1]$ we have $1-\gamma \mu > 1-\gamma L \geq 0$. Let:%
$$
    \beta_{i+1}(\m) {}{}\coloneqq{}{} {-1} + \m \Ei[i+1][\m] {}={} \frac{1 + \m + \dots + \m^{2i}}{\m^{2i+1}} > 0.
$$%
Inequality \eqref{eq:dist_1_mu_1_step_decrease} results after performing the simplifications in the linear combination of interpolation inequalities:%
$$
\Iij[i][i+1] + \beta_{i+1}(\m) \, (\Iij[i][i+1] + \Iji[i][i+1]),$$
where \eqref{eq:distance-N_interpolation_conditions_I_ij} and \eqref{eq:distance-N_interpolation_conditions_I_ji} equivalently rewrite for the pair $(i,i+1)$ as:
\begin{align*}
    (1+ \beta_{i+1}) {\,} \Iij[i][i+1] {}:{}\,{}{} 
        \frac{f_{i} {-} f_{i+1}}{\gamma}
            {}\geq{} &
        \frac{\|g_{i}\|^2}{2} {+} \frac{1}{\m} \frac{\|g_{i+1}\|^2}{2} {+} \frac{\frac{\n}{\m}}{\m{-}\n} \frac{\|g_{i+1}{-}\m g_{i}\|^2}{2}; \\    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
     \beta_{i+1} {\,} \Iji[i][i+1] {}:{}\,{}{}
        \frac{f_{i+1} {-} f_{i}}{\gamma}
            {}\geq{} &
        {-}(1{+}\m) \frac{\|g_{i}\|^2}{2} {+} \frac{1}{\m{-}\n} \frac{\|g_{i+1}{-}\m g_{i}\|^2}{2}.
\end{align*}%
Condition $\gamma L < \gbari[i+1]$ implies $\Tinm[i+1] < 0$, hence $i \geq \Nbar$ (recall \cref{def:N_bar}: $\Tinm[\bar{N}] \geq 0$ and $\Tinm[\bar{N}+1] < 0$, corresponding to $\gamma L < \gbari[\bar{N}+1]$). Then the coefficient of the mixed term in \eqref{eq:dist_1_mu_1_step_decrease} is positive:%
$$
    \frac{{-1} {+} (\m{+}\n) E_{i+1}(\m)}{\m{-}\n} 
        {}\geq{} 
    \frac{{-1} {+} (\m{+}\n) E_{\bar{N}+1}(\m)}{\m{-}\n}
        {}={}
    \frac{\Tinm[\bar{N}]{-}\n^2 \Tinm[\bar{N}+1]}{(\m{-}\n)^2} 
        {}>{} 0.
$$
The first inequality results from the monotonic increase with index $i$ of $E_{i+1}(\m)$, whereas the last one by the definition of $\Nbar$.%
\qed \end{proof}

\begin{lemma}[Central distance-2 result]\label{lemma:telescoped_main_lemma}
Let $f \in \mathcal{F}_{\mu,L}$, with $\mu \in (-\infty, L)$. Consider $k+1$ iterations of \eqref{eq:GM_it_fixed_steps} with constant stepsize $\gamma L \in \big[\gbari[k], \gbari[\infty] \big)$ starting from $x_0$, where $k \geq 1$. Then it holds:%
\begin{align}
        & \frac{f(x_{0}) {-} f(x_{k})}{\gamma} +
        \frac{(\m{+}\n)\Tinm[k]}{2(\m{-}\n)} \frac{f(x_{k}) {-} f(x_{k+1})}{\gamma}
            \geq
        % \\ & {}\qquad{}
        \left(\Ei[k][\m] {+} \Ei[k][\n]\right) \frac{\|\nabla f(x_{k})\|^2}{4} +
        \nonumber \\ & {}\quad{}\,
        {}+{}\frac{\Tinm[k]}{2(\m{-}\n)} \Big[ \m \n \frac{\|\nabla f(x_{k})\|^2}{2} + 
        \langle \nabla f(x_{k}) , \nabla f(x_{k+1}) \rangle + 
        \frac{\|\nabla f(x_{k+1})\|^2}{2} \Big]. \label{eq:telescoped_main_lemma} \tag{D2}
\end{align}%
\end{lemma}

\begin{proof}
Consider two iterations connecting $x_{i}$, $x_{i+1}$ and $x_{i+2}$, with $i \geq 0$. The interpolation inequalities \eqref{eq:distance-N_interpolation_conditions_I_ij} and \eqref{eq:distance-N_interpolation_conditions_I_ji} written for distance-1 (\Iij[i][i+1] and \Iji[i][i+1]) and distance-2 (\Iij[i][i+2] and \Iji[i][i+2]), respectively:%
\begin{align*}
    &\begin{aligned}    
    % & \alpha_{[i-1>i]} \times 
    \Iij[i][i+1]\colon 
        \frac{f_{i} - f_{i+1}}{\gamma}
            {}\geq{}
        (1+\n) \frac{\|g_{i}\|^2}{2} + \frac{1}{\m-\n} \frac{\|g_{i+1}-\n g_{i}\|^2}{2}; 
    \end{aligned}\\
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    &\begin{aligned}    
    % & \alpha_{[i-1<i]}  \times 
    \Iji[i][i+1]\colon 
        \frac{f_{i+1} - f_{i}}{\gamma}
            {}\geq{}
        -\frac{\|g_{i}\|^2}{2} - \frac{1}{\n} \frac{\|g_{i+1}\|^2}{2} + \frac{\m}{\n} \frac{1}{\m-\n} \frac{\|g_{i+1}-\n g_{i}\|^2}{2}; 
    \end{aligned}\\
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    &\begin{aligned}    
    &% \alpha_{[i-1>i+1]}  \times 
    \Iij[i][i+2]\colon 
        \frac{f_{i} - f_{i+2}}{\gamma}
            {}\geq{}
        (1+\n+\n^2) \frac{\|g_{i}\|^2}{2} + \n \frac{\|g_{i+1}\|^2}{2} + 
        \frac{1}{\n(\m-\n)} \cdot
        \\ & {}\qquad{}        
        \Big[
        \n(1-\m) \frac{\|g_{i+1}-\n g_{i}\|^2}{2}
        - (1-\n) \frac{\|g_{i+2}-\n g_{i+1}\|^2}{2}
        + \frac{\|g_{i+2}-\n^2 g_{i}\|^2}{2} 
        \Big];
    \end{aligned}\\
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    &\begin{aligned}    
    &% \alpha_{[i-1<i+1]}  \times 
    \Iji[i][i+2]\colon
        \frac{f_{i+2} - f_{i}}{\gamma}
            {}\geq{} 
        - \frac{\|g_{i}\|^2}{2} - \frac{1}{\n} \frac{\|g_{i+1}\|^2}{2}
        - \frac{1+\n}{\n^2} \frac{\|g_{i+2}\|^2}{2} + \frac{1}{\n(\m-\n)} \cdot
        \\ & {}\qquad{} 
        \Big[
        \m(1-\n) \frac{\|g_{i+1}-\n g_{i}\|^2}{2}
        - (1-\m) \frac{\|g_{i+2}-\n g_{i+1}\|^2}{2}
        + \frac{\m}{\n} \frac{\|g_{i+2}-\n^2 g_{i}\|^2}{2} 
        \Big],
    \end{aligned}
\end{align*}%
are summed up in a linear combination with \textit{nonnegative} corresponding weights:%
$$
        \eqref{eq:dist_2_atom_ineq} \equiv
\alphaij[i][i+1] \Iij[i][i+1] +
\alphaij[i+1][i] \Iji[i][i+1] +
\alphaij[i][i+2] \Iij[i][i+2] +
\alphaij[i+2][i] \Iji[i][i+2],
$$%
where:%
$$
\begin{aligned}
    \alphaij[i][i+1] {}{}\coloneqq{}{}& 
    1 - \n \Ei[i+1][\n] + \frac{(1-\m) \Tinm[i]}{2(\m-\n)} - \frac{\m(1+\n) \Tinm[i+1]}{2(\m-\n)};
    \\
   \alphaij[i+1][i] {}{}\coloneqq{}{}& 
    -\n \Ei[i+1][\n] + \frac{(1+\n) \Tinm[i]}{2(\m-\n)} + \frac{\n(1-\m) \Tinm[i+1]}{2(\m-\n)};
    \\
    \alphaij[i][i+2] {}{}\coloneqq{}{}&
     \frac{\m \Tinm[i+1]}{2(\m-\n)}; 
     \\
    \alphaij[i+2][i] {}{}\coloneqq{}{}&
    \frac{-\n \Tinm[i+1]}{2(\m-\n)},
\end{aligned}%
$$%
and \eqref{eq:dist_2_atom_ineq} is obtained after performing the simplifications:%
\begin{align}\label{eq:dist_2_atom_ineq}    
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \begin{aligned}
        &
        \frac{f_{i} {-} f_{i+1}}{\gamma} + 
        (\m{+}\n) \Big[
        {-}\frac{\Tinm[i]}{2(\m{-}\n)} \frac{f_{i} {-} f_{i+1}}{\gamma} +
           \frac{\Tinm[i+1]}{2(\m{-}\n)} \frac{f_{i+1} {-} f_{i+2}}{\gamma}
        \Big]
            {}\geq{}
        \\ & {}\,{} 
        {}{-}{}\frac{\Tinm[i]}{2(\m{-}\n)} \Big[ \m \n \frac{\|g_{i}\|^2}{2} + 
        \langle g_{i}, g_{i+1} \rangle + \frac{\|g_{i+1}\|^2}{2}  \Big] 
        {-}\left(\Ei[i][\m] {+} \Ei[i][\n]\right) \frac{\|g_{i}\|^2}{4}
        \\ & {}\,{} 
        {}{+}{}\frac{\Tinm[i+1]}{2(\m{-}\n)} \Big[ \m \n \frac{\|g_{i+1}\|^2}{2} 
        {+} {\langle g_{i+1}, g_{i+2} \rangle} + \frac{\|g_{i+2}\|^2}{2}  \Big] {}+{} \left(\Ei[i+1][\m] {+} \Ei[i+1][\n]\right) \frac{\|g_{i+1}\|^2}{4}.
    \end{aligned}
\end{align}%
\noindent{}Telescoping it for indices $i=0,1,\dots,k-1$ yields inequality \eqref{eq:telescoped_main_lemma}. It remains to show the nonnegativity of multipliers. Since the stepsize thresholds increase with index $i$, condition $\gamma L \geq \gbari[k]$ ensures $\Tinm[i+1] \geq 0$, for all $i=0,{\dots},k-1$. This directly implies the positivity of $\alphaij[i][i+2]$ and $\alphaij[i+2][i]$. The positivity of distance-1 multipliers is evidenced by their equivalent representations as nonnegative sums (recall $\n \in (-1,0)$, $\m \in \left(0,\infty\right)$; $\m+\n>0$ and $\n^{-2} > \m^{-2}$ from \cref{prop:properties:m+n>0}):%
$$
\begin{aligned}
    &\begin{aligned}    
    2\alphaij[i][i+1] {}={}& 
    1 + \frac{\m+\m^{-2i}}{1+\m} + 
    \frac{(1+\n)(\m+\n-\n\m)}{\m \n^2} \frac{{-1} +\n^{-2(i+1)}}{{-1} +\n^{-2}} + 
    \\& {}\qquad\qquad{}
    \frac{(1+\n)(1+\m^2)}{\m(\m-\n)} 
    % \Big[ \frac{1-\n^{-2i}}{1-\n^{-2}} - \frac{1-\m^{-2i}}{1-\m^{-2}} \Big] 
    \sum_{j=0}^{i} \big(\n^{-2j} - \m^{-2j}\big)
    {}>{} 0;  
    \end{aligned} \\%
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    &\begin{aligned}  
    2\alphaij[i+1][i] {}={}&
    \frac{{-1} +\n^{-2i}}{1-\n} + 
    \frac{\m(1+\n)}{1-\n} \frac{{-1} +\m^{-2(i+1)}}{1-\m}
    + \\& {}\qquad\qquad{}
     +\frac{-\n \big[1-\n+\m(1+\n)\big]}{1-\n} \frac{\n^{-2(i+1)} - \m^{-2(i+1)}}{\m-\n} > 0. 
    % {}\qquad\qquad\qquad\qquad\qquad{}
    {}\qquad{}
    {}\qed{}
    \end{aligned}%
\end{aligned}
$$%
\end{proof}

\begin{lemma}[Multistep descent]\label{lemma:hypo_GN4SD}
Let $f \in \mathcal{F}_{\mu,L}$, with $\mu \in (-\infty, L)$, and consider $k+1 {}\geq{} 1$ iterations of \eqref{eq:GM_it_fixed_steps} with stepsize $\gamma L \in [\gbari[k], \gbari[\infty])$, {\shownewtext{satisfying $\gamma L > 1$,}} starting from $x_0$. Then the following inequality holds:%
\begin{align}%
% \hspace{-.25em}
    \frac{f(x_0) {-} f(x_{k+1})}{\gamma}
        {}\geq{}
    \frac{{-}\m^2 \n^2 \Tinm[k+1]}{\m^2{-}\n^2} \frac{\|\nabla f(x_{k})\|^2}{2} {}+{}
    \frac{\Tinm[k]{+}(\m{-}\n)}{\m^2{-}\n^2} \frac{\|\nabla f(x_{k+1})\|^2}{2}.
\label{eq:general_ineq_proof} \tag{GN4SD}
% \tag{$I_{N+1}^{N}$}
\end{align}%
Furthermore, if $\mu \in (-\infty, 0]$ and $\gamma L \in [\gbari[k], \gbari[k+1])$, then the gradient norms from \eqref{eq:general_ineq_proof} are weighted by nonnegative quantities.
\end{lemma}

\begin{proof}%
For $k=0$, the result follows from \cref{lemma:sufficient_decrease_h_geq_1} and we obtain exactly \eqref{eq:one_step_rate_h_geq_1}. 
For $k\geq 1$, inequality \eqref{eq:general_ineq_proof} is derived by adjusting \eqref{eq:telescoped_main_lemma} through the linear combination of interpolation inequalities $\alphaij[k][k+1] \Iij[k][k+1] + \alphaij[k+1][k] \Iji[k][k+1]$:%
$$
    \begin{aligned}
        &  \Big[1 - \frac{(\m+\n)\,\Tinm[k]}{2(\m-\n)} \Big] \frac{f_{k} - f_{k+1}}{\gamma}
        {}\geq{}
        \\ & {}\qquad{}
        \Big(-\Ei[k][\m] - \Ei[k][\n] - \frac{\m \n \Tinm[k]}{\m-\n} {}-{} \frac{2\m^2\n^2 \Tinm[k+1]}{\m^2-\n^2} \Big) \frac{\|g_{k}\|^2}{4}
        \\ & {}\qquad{}        
        % \\ & {}\qquad{}
        {}+{} \Big(\frac{\m-\n + \Tinm[k]}{\m^2-\n^2} - \frac{\Tinm[k]}{2(\m-\n)} \Big) \frac{\|g_{k+1}\|^2}{2}
        {}-{}\frac{\Tinm[k]}{2(\m-\n)} \langle g_{k},g_{k+1} \rangle,
    \end{aligned}
$$%
where the corresponding weights are defined as follows:%
    $$
    \begin{aligned}
        \alphaij[k][k+1]
             {}{}\coloneqq{}{} &
        1 + \frac{-\n}{\m+\n} + \frac{(1-\m)(\m+\n)-2\n}{2(\m^2-\n^2)} \Tinm[k];  \\
        %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
        \alphaij[k+1][k]
            {}{}\coloneqq{}{} &
        \frac{-\n}{\m+\n} + \frac{(1+\n)(\m+\n)-2\n}{2(\m^2-\n^2)} \Tinm[k].
    \end{aligned}
    $$ %
    Multiplier $\alphaij[k+1][k]$ is represented as a sum of positive quantities ($\n < 0$).
    Multiplier $\alphaij[k][k+1]$ is directly written as sum of positive quantities if $(1-\m)(\m+\n)-2\n > 0$ (in particular, this covers the (strongly) convex case where $\m \leq 1$). Otherwise, $\alphaij[k][k+1]$ is equivalently expressed as a sum of positive terms as follows, with $\m>1$:%
$$
\begin{aligned}
    \alphaij[k][k+1]
        {}={}&
    \frac{\m}{2(\m+\n)} + \frac{1}{2(\m^2-\n^2)} 
        \bigg[ \frac{-\n(\m-\n)(1+\m^2)}{(\m-1)(1-\n)} {}+{}
        \\ & {}\quad{} 
        -\big[(1-\m)(\m+\n)-2\n\big] \Big( \frac{\m^{-2k}}{\m-1} + \frac{\n^{-2k}}{1-\n} \Big)  \bigg]
        {}>{} 0. {}\quad{} \qed
\end{aligned}
$$
\end{proof}

\begin{lemma}\label{lemma:general_lemma_ct_h_to_Linear} 
Let $f \in \mathcal{F}_{\mu,L}$, with $\mu \in (-\infty, L)$, and consider $k+1 \geq 1$ iterations of \eqref{eq:GM_it_fixed_steps} with stepsize $\gamma L \in [\gbari[k], \gbari[\infty] \big)$, satisfying $\gamma L > 1$, starting from $x_0$. Then the following inequality holds:%
\begin{align}\label{eq:general_ineq_proof_to_linear_compact}
   \frac{f(x_0) {-} f(x_{k+1})}{\gamma}
        {}\geq{} 
    \Ei[k+1][\n] \frac{\|\nabla f(x_{k+1})\|^2}{2} {+} 
    \frac{\m^2 \Tinm[k+1]}{(\m{-}\n)^2}
    \frac{\| \nabla f(x_{k+1}) {-} \n \nabla f(x_{k}) \|^2}{2}.
\end{align}%
Furthermore, if $\gamma L \in [\gbari[k+1], \gbari[\infty] \big)$, then $\Tinm[k+1]\geq 0 $.%
\end{lemma}

\begin{proof}%
For $k=0$, the result follows from \cref{lemma:dist_1_L_1_step_decrease}. For $k \geq 1$, inequality \eqref{eq:general_ineq_proof_to_linear_compact} is derived by adjusting \eqref{eq:telescoped_main_lemma} with the linear combination of interpolation inequalities $\alphaij[k][k+1] \Iij[k][k+1] + \alphaij[k][k+1] \Iji[k][k+1]$:%
$$
    % \hspace{-1em}
    \begin{aligned}
        &\Big[1 - \frac{(\m+\n)\,\Tinm[k]}{2(\m-\n)} \Big] \frac{f_{k} - f_{k+1}}{\gamma}
            {}\geq{}
        \Big(-\frac{\Tinm[k]}{2(\m-\n)} - \frac{\m^2 \n \Tinm[k+1]}{(\m-\n)^2}\Big) \langle g_{k},g_{k+1} \rangle {}+{}
        \\ & {}\quad\qquad{}
        {}+{} \Big[ \frac{2\m^2 \n^2 \Tinm[k+1]}{(\m-\n)^2} -\Ei[k][\m] - \Ei[k][\n] - \frac{\m \n \Tinm[k]}{\m-\n} \Big] \frac{\|g_{k}\|^2}{4} {}+{}
        \\ & {}\quad\qquad{}
        {}+{} \Big[ \frac{\m^2 \, \Tinm[k+1]}{(\m-\n)^2}  + \Ei[k+1][\n] -\frac{\Tinm[k]}{2(\m-\n)} \Big] \frac{\|g_{k+1}\|^2}{2},
    \end{aligned}
$$%
where the corresponding weights are defined as:
$$
\begin{aligned}
    \alphaij[k][k+1] 
        {}{}\coloneqq{}{} &
    1+(-\n)\Ei[k+1][\n] + \frac{1-\m}{2(\m-\n)} \Tinm[k];
    \\
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \alphaij[k+1][k]
        {}{}\coloneqq{}{} &
    (-\n) \Ei[k+1][\n] + 
    \frac{1+\n}{2(\m-\n)} \Tinm[k].
\end{aligned}%
$$%
Multiplier $\alphaij[k+1][k]$ is represented as a sum of positive quantities, while $\alphaij[k][k+1]$ is directly written as sum of positive terms if $\m \leq 1$ (the (strongly) convex case). Otherwise, $\m > 1$ and $\alphaij[k][k+1]$ is equivalently expressed as sum of positive terms as:%
$$
        \alphaij[k][k+1]
    {}={}
        \frac{1+(-\n) \n^{-2(k+1)}}{2(1-\n)} + \m \frac{\m \m^{-2(k+1)} + (-\n) \n^{-2(k+1)}}{2(\m-\n)}. {}\quad{} \qed
$$
\end{proof}

\begin{lemma}\label{lemma:general_lemma_ct_h_to_Linear_mu} 
Let $f \in \mathcal{F}_{\mu,L}$, with $\mu \in (-\infty,L)$, and consider $k+1 \geq 1$ iterations of \eqref{eq:GM_it_fixed_steps} with stepsize $\gamma L \in [\gbari[k], \gbari[\infty])$, satisfying $\gamma L > 1$, starting from $x_0$. Then the following inequality holds:%
\begin{align}\label{eq:general_ineq_proof_to_linear_mu_compact}
% \hspace{-.75em}
    \frac{f(x_0) {-} f(x_{k+1})}{\gamma}
        {\geq}
    \Ei[k+1][\m] \frac{\|\nabla f(x_{k+1})\|^2}{2} {+} 
    \frac{-\n^2 \Tinm[k+1]}{(\m{-}\n)^2}
    \frac{\| \nabla f(x_{k+1}) {-} \m \nabla f(x_{k}) \|^2}{2}.
\end{align}%
Furthermore, if $\gamma L \in [\gbari[k], \gbari[k+1] \big)$, then $\Tinm[k+1]<0$.
\end{lemma}

\begin{proof}[\textbf{\cref{thm:strg_cvx_rate}}]\label{proof:thm:strg_cvx_rate}%
We split the proof over stepsize intervals:%
\[
    (0,2) 
        {}={}
    \big(0, \gbari[1]\big] \cup
    \Big( \mathop{\cup}\limits_{k=1}^{N-1} \big[\gbari[k],\gbari[k+1]\big)\Big)
    {}\cup{} \big[\gbari[N],\tfrac{2}{1+\kappa}\big) 
    {}\cup{} \big[\tfrac{2}{1+\kappa}, 2\big).
\]%
%
\begin{enumerate}[align=right,itemindent=1em,labelsep=2pt,labelwidth=1em,leftmargin=0pt,nosep]%
\item \textbf{Case $\gamma L \in \big(0, \gbari[1]\big]$}. By telescoping \eqref{eq:dist_1_mu_1_step_decrease} for indices $i=0,\dots,N-1$:%
$$
        \frac{f_{0} - f_{N}}{\gamma} 
            {}\geq{}
        \Ei[N][\m] \frac{\|g_{N}\|^2}{2} {}+{}        
            \sum_{i=0}^{N-1}
            \frac{ {-1} + (\m+\n) \Ei[i+1][\m] }{\m-\n} \frac{\|g_{i+1}-\m g_{i}\|^2}{2},
$$%
where all mixed terms have nonnegative coefficients because $\gamma L \in \big(0,  \gbari[1]\big]$ (see \cref{lemma:dist_1_mu_1_step_decrease}). Hence they can be neglected to obtain the lower bound of type \eqref{eq:I^k_N_general_ineq}:
\begin{align}\label{eq:sufficient_decrease_N_its_mu_strongly_convex_towards_rate_no_dist_2}
    \frac{f_0 - f_N}{\gamma}
        {}\geq{}
    \Ei[N][\m] \frac{\|g_{N}\|^2}{2}.
\end{align}%:
\item \textbf{Case $\gamma L \in \big[\gbari[k],\gbari[k+1]\big)$}, with some $k \in \{1,\dots,N-1\}$. By telescoping \eqref{eq:dist_1_mu_1_step_decrease} for indices $i=k+1,\dots,N-1$:%
$$
\begin{aligned}
        \frac{f_{k+1} {-} f_{N}}{\gamma} 
            {}\geq{} &
        {-}\Ei[k+1][\m] \frac{\|g_{k+1}\|^2}{2} {+}
        \Ei[N][\m] \frac{\|g_{N}\|^2}{2} {+} \\
        & \quad     \sum_{i{=}k{+}1}^{N{-}1}
            \frac{ {-1} {+} (\m{+}\n) \Ei[i{+}1][\m] }{\m{-}\n} \frac{\|g_{i+1}{-}\m g_{i}\|^2}{2},
\end{aligned}
$$%
with nonnegative weights of the mixed terms since $\gamma L \in \big(0,  \gbari[k+1]\big)$ (see \cref{lemma:dist_1_mu_1_step_decrease}). After appending it to \eqref{eq:general_ineq_proof_to_linear_mu_compact} from \cref{lemma:general_lemma_ct_h_to_Linear_mu}, we obtain:%
$$
\begin{aligned}
    \frac{f_0 {-} f_N}{\gamma}
        {}\geq{}
    \Ei[N][\m] \frac{\|g_{N}\|^2}{2} +
    \frac{-\n^2 \, \Tinm[k+1]}{(\m-\n)^2} \, 
    \frac{\| g_{k+1} - \m g_{k} \|^2}{2} +     \\
    \sum_{i=k+1}^{N-1}
            \frac{ {-1} + (\m+\n) \Ei[i+1][\m] }{\m-\n} \frac{\|g_{i+1}-\m g_{i}\|^2}{2}.
\end{aligned}
$$
Since $\Tinm[k+1] < 0$, all mixed terms can be neglected to get a \eqref{eq:I^k_N_general_ineq}-type inequality:%
\begin{align}\label{eq:sufficient_decrease_N_its_mu_strongly_convex_towards_rate}
    \frac{f_0 - f_N}{\gamma}
        {}\geq{}
    \Ei[N][\m] \frac{\|g_{N}\|^2}{2}.
\end{align}%
%
 \item \textbf{Case $\gamma L \in \big[\gbari[N],\frac{2}{1+\kappa}\big)$.} From \cref{lemma:general_lemma_ct_h_to_Linear} with $k=N-1$ it holds:%
$$
   \frac{f_0 - f_N}{\gamma}
        {}\geq{}
    \Ei[N][\n] \frac{\|g_N\|^2}{2} + 
    \frac{\m^2 \, \Tinm[N]}{(\m-\n)^2} \, 
    \frac{\| g_N - \n g_{N-1} \|^2}{2}.
$$%
Since $\TigLmu[N] \geq 0$, by neglecting the mixed term we obtain a \eqref{eq:I^k_N_general_ineq}-type inequality:
\begin{align}\label{eq:wc_linear_L}
    \frac{f_0 - f_N}{\gamma}
        {}\geq{}
    \Ei[N][\n] \frac{\|g_{N}\|^2}{2}.
\end{align}%
%
\item \textbf{Case $\gamma L \in \big[\frac{2}{1+\kappa},2\big)$.} By telescoping \cref{lemma:dist_1_L_1_step_decrease} for $i=0,1,\dots,N-1$ it holds:%
$$
    \frac{f_{0} - f_{N}}{\gamma} 
                {}\geq{}
            \Ei[N][\n] \frac{\|g_{i}\|^2}{2} +
            \sum_{i=0}^{N-1} \frac{ 1 - (\m+\n) \Ei[i+1][\n] }{\m-\n} \frac{\|g_{i+1}-\n g_{i}\|^2}{2},
$$%
where the mixed terms can be neglected and then the inequality reduces to \eqref{eq:wc_linear_L}.%
\end{enumerate}%
Since the transition between the two linear regimes is given by the sign of $\Tinm[N]=\Ei[N][\m]{-}\Ei[N][\n]$, we can glue together expressions \eqref{eq:sufficient_decrease_N_its_mu_strongly_convex_towards_rate_no_dist_2}, \eqref{eq:sufficient_decrease_N_its_mu_strongly_convex_towards_rate} and \eqref{eq:wc_linear_L}:%
$$
    \frac{f_0 - f_N}{\gamma}
        {}\geq{}
    \min\left\{ \Ei[N][\m] \,,\, \Ei[N][\n]\right\} \frac{\|g_{N}\|^2}{2},
$$%
equivalent to:
$$
    f_0 - f_N
        {}\geq{}
    \min
    \Big\{ \frac{{-1} +(1-\gamma \mu)^{-2N}}{\mu} \,,\, 
    \frac{{-1} +(1-\gamma L)^{-2N}}{L}
    \Big\} \frac{\|g_{N}\|^2}{2},
$$%
which implies the bound \eqref{eq:strg_cvx_full_ct} and the complementary one:
$$
\begin{aligned}
    \frac{1}{2L} \|\nabla f(x_N)\|^2
        {} \leq {}  
    \frac{f(x_0)-f(x_N)}
    { \min\big\{ \frac{L}{\mu} \left[{-1}+(1-\gamma \mu)^{-2N}\right] \,,\, {-1}+(1-\gamma L)^{-2N} \big\} }. {}\qquad{}\qed 
\end{aligned}%
$$%
\end{proof}

\begin{proof}[\textbf{\cref{prop:monotonicity_Tk}}] \label{appendix:proof_prop_monotonicity_Tk}
We show $\frac{d\TigLmu}{d (\gamma L)} \geq 0$ for $\gamma L \in (1, \gbari[\infty])$, which resumes to prove the positivity of
  \begin{align*}
        \frac{d \delta_i(\gamma L, \kappa)}{d(\gamma L)}
            {}{}\coloneqq{}{}
      \frac{-\kappa \left( 1 - 2i \frac{2-\kappa \gamma L}{1-\kappa \gamma L} \right) }{(1-\kappa \gamma L)^{2i}} + \frac{ 1 + 2i \frac{2-\gamma L}{\gamma L-1}}{(1-\gamma L)^{2i}}.
  \end{align*}
  \begin{enumerate}[align=right,itemindent=1em,labelsep=2pt,labelwidth=1em,leftmargin=0pt,nosep]
      \item \textbf{Case $\kappa \geq 0$:} we lower bound $\frac{d \delta_i(\gamma L, \kappa)}{d(\gamma L)}$ by neglecting the denominators:
      \begin{align*}
          \delta_i(\gamma L, \kappa) 
            {}\geq{} 
          {-}\kappa \Big( 1 - 2i \frac{2-\kappa \gamma L}{1-\kappa \gamma L} \Big) + 1 + 2i \frac{2-\gamma L}{\gamma L-1}
            {}={}
          (1-\kappa) + 2i \Big[ \frac{\kappa (2-\kappa \gamma L)}{1-\kappa \gamma L}  + \frac{2-\gamma L}{\gamma L-1} \Big] {}\geq{} 0.
      \end{align*}%
        %
      \item \textbf{Case $\kappa < 0$:} it is sufficient to show 
    \begin{align*}
        \frac{1+2i \frac{2-\gamma L}{\gamma L -1}}{(1-\gamma L)^{2i}}
            {}\geq{} 1 {}\geq{}
        -\kappa \frac{-1+2i (1 + \frac{1}{1-\kappa \gamma L})}{(1-\kappa \gamma L)^{2i}}.
    \end{align*}
      The \lhs holds because $\gamma L \in (1,2)$ and $(1-\gamma L)^{2i}<1$. The \rhs is equivalent to:%
      \begin{align*}
          (1-\kappa \gamma L)^{2i} {}\geq{} -\kappa \Big[-1+2i \Big(1 + \frac{1}{1-\kappa \gamma L}\Big)\Big].
      \end{align*}
Using $\gamma L \in (1,2)$ and the second order Taylor approximation for $(1-\kappa)^{2i}$, we get the bounds:%
      \begin{align*}
          (1-\kappa \gamma L)^{2i} {}\geq{}& (1-\kappa)^{2i} 
             {}\geq{} 
         1 + 2i (-\kappa) + i(2i-1) \kappa^2 \\
         %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
          -\kappa \Big[-1+2i \Big(1 + \frac{1}{1-\kappa \gamma L}\Big)\Big]
            {}\leq{}&
          -\kappa \Big[-1+2i \left(1 + \frac{1}{1-\kappa}\right)\Big].
      \end{align*}
Therefore, it is sufficient to show:%
$$
    1 + 2i (-\kappa) + i(2i-1) \kappa^2 {}\geq{} 
    -\kappa \Big[-1+2i \Big(1 + \frac{1}{1-\kappa}\Big)\Big],%
$$%
which equivalently rewrites as the following inequality valid for all $i \geq 1$:
$$
    \kappa^2 i(i-1) + \Big( \kappa i + \frac{1}{1-\kappa} \Big)^2 + \frac{(1-\kappa)^3-1}{(1-\kappa)^2} \geq 0. {}\qquad \qed{}%
$$%
\end{enumerate}
\end{proof}

\begin{lemma} \label{lemma:unique_delta_k_neg_thr}
Let $\kappa \in (-\infty, 1)$ and $\gamma L \in (1,\gbari[\infty])$. Then there exists an index $k$ such that $\delta_k(\gamma L, \kappa) < 0$ and $\delta_j(\gamma L, \kappa) < 0$ for all $j > k$.    
\end{lemma}

\begin{proof}
    The sequence $\delta_i$ is a difference of two monotone sequences: $\frac{2-\kappa \gamma L}{(1-\kappa \gamma L)^{2i}}$ and $\frac{2-\kappa \gamma L}{(1-\kappa \gamma L)^{2i}}$, respectively. The former is decreasing for $\kappa < 0$ (weakly convex functions) and increasing for $\kappa \geq 0$ (convex functions), whereas the later is always decreasing. In particular, $\delta_0(\gamma L, \kappa) > 0$. 
    Because $(1-\gamma \mu)^2 {}\leq{} (1-\gamma L)^2$, to the limit it holds $\lim_{k \rightarrow \infty} \delta_k(\gamma L, \kappa) = -\infty$ and there exists some index $k$ with $\delta_k(\gamma L, \kappa) < 0$. We prove by contradiction that $\delta_j(\gamma L, \kappa) < 0$ for all $j > k$; assume there exists some index $l > k$ such that $\delta_l(\gamma L, \kappa) \geq 0$. The following inequalities hold:%
\begin{align*}
    \delta_{k} < 0 \,:\,& 
        \frac{2-\gamma \mu}{(1-\gamma \mu)^{2k}} 
            {}<{} 
        \frac{2-\gamma L}{(1-\gamma L)^{2k}} \\
    %%%%%%%%%%%%%%%%%%%%%%%%%%%
    \delta_{l} > 0 \,:\,& 
        \frac{2-\gamma \mu}{(1-\gamma \mu)^{2l}} 
            {}>{} 
        \frac{2-\gamma L}{(1-\gamma L)^{2l}}.
\end{align*}
By multiplying the inequalities and performing the simplifications we get:%
\begin{align*}
    (1-\gamma \mu)^{2(k-l)} > (1-\gamma L)^{2(k-l)},
\end{align*}
which implies, due to $(1-\gamma \mu)^2 {}>{} (1-\gamma L)^2$, that $k > l$, contradiction! \qed
\end{proof}

\begin{proof}[\textbf{\cref{prop:properties_step_size_thr}}] \label{appendix:proof_properties_step_size_thr} 
\begin{enumerate}[align=right,itemindent=1em,labelsep=2pt,labelwidth=1em,leftmargin=0pt,nosep]
\item Case $k=0$ holds by definition since $\gbari[0]=1$. For any $k \geq 1$, by using \cref{lemma:unique_delta_k_neg_thr}, condition $\TigLmu[k][\gbari[k][]] = 0$ implies $\delta_k(\gamma L, \kappa) \leq 0$ and hence $\delta_{k+1}(\gamma L, \kappa) < 0$. Furthermore, $\TigLmu[k+1][\gbari[k][]] {} \leq {} \TigLmu[k][\gbari[k][]] = 0$. Then it holds:
\begin{align*}
    \TigLmu[k+1][\gbari[k][]] {} \leq {} 
    \TigLmu[k][\gbari[k][]] = 0 
    {}={} \TigLmu[k+1][\gbari[k+1][]].
\end{align*}
The monotonicity of $\TigLmu$ in stepsize $\gamma L$ (see \cref{prop:monotonicity_Tk}) implies $\gbari[k] < \gbari[k+1]$.

\item Because stepsize thresholds sequence is monotone, it has a limit.
\begin{enumerate}[align=right,itemindent=1.5em,labelsep=2pt,labelwidth=1em,leftmargin=0pt,nosep]
    %%%%%%%%%%%%%%%%%%%%%%%%%% 2. %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \item 
    \textbf{Case $\kappa > 0$.} By definition, $\gbari[k] < \frac{2}{1+\kappa} < 2$ for all integers $k\geq 1$ and condition $\TigLmu[k][\gbari[k]]=0$ implies:%
    \begin{align*}
        \left(\frac{1-\gbari}{1-\kappa \gbari}\right)^{2k}
            {}={}& 
        \kappa + (1-\kappa) (1-\gbari)^{2k}
            {}\Leftrightarrow{} \\
            %%%%%%%%%%%%%%%%%%%%%%%%%%%%
        \left|\frac{1-\gbari}{1-\kappa \gbari}\right|
            {}={}&
        \exp \left[ \frac{\ln \left(\kappa + (1-\kappa) (1-\gbari)^{2k}\right)}{2k} \right].
    \end{align*}%
    To the limit $k \rightarrow \infty$, the \rhs equals $1$ because $(1-\gbari)^{2k}\rightarrow 0$, hence $|1-\gbari|=|1-\kappa \gbari|$, which implies the solution $\gbari[\infty]=\frac{2}{1+\kappa}$. \\
    %%%%%%%%%%%%%%%%%%%%%%%%%%
    \item \textbf{Case $\kappa < 0$.} By definition, $\gbari < 2$ for all integers $k\geq 1$ and condition $\TigLmu[k][\gbari[k]]=0$ implies:
    \begin{align*}
    (1-\gbari)^{-2k} 
        {}={}&
    1 + \frac{1 - (1-\kappa \gbari)^{-2k}}{-\kappa}
        {}\Leftrightarrow{} \\
    % %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \left|1-\gbari\right| 
        {}={}&
    \exp \Bigg[ \frac{ -\ln \Big(1 + \frac{1 - (1-\kappa \gbari)^{-2k}}{-\kappa}\Big)}{2k} \Bigg].
\end{align*}
 To the limit $k \rightarrow \infty$, the \rhs equals $1$ because $(1-\kappa \gbari)^{-2k} \rightarrow 0$ due to $\kappa < 0$. Hence, $\left|1-\gbari\right|=1$, with the solution $\gbari[\infty]=2$.%
 %
\item \textbf{Case $\kappa = 0$.} By definition, $\gbari[k][(0)] < 2$ and, similarly to the case $\kappa < 0$:%
 \begin{align*}
     \left|1-\gbari\right|
        {}={}&
     \left[ 1 + 2 k \gbari \right]^{\frac{-1}{2k}}
        {}={}
    \exp \Big[ \frac{-\ln \big( 1 + 2 k \gbari \big) }{2k} \Big].
 \end{align*}
  To the limit $k \rightarrow \infty$, the \rhs equals $1$, hence $\left|1-\gbari\right|=1$, with the solution $\gbari[\infty]=2$.
\end{enumerate}%
%
\item Condition $\gamma L \in [\gbari[k], \gbari[k+1])$ implies $\TigLmu[k][\gbari[k]] \geq 0$ and $\TigLmu[k+1][\gbari[k]] < 0$. Because $\delta_i(\gamma L, \kappa) < 0$ for all $i \geq k$, we have (i) $\TigLmu[i][\gbari[k][]] {}>{} 0$ for $i=1,\dots,k-1$ (since $k$ is uniquely defined) and (ii) $\TigLmu[i][\gbari[k][]] {}<{} 0$ for $i\geq k+1$. {}\qed{}%
\end{enumerate}
\end{proof}

