\noindent {\textbf{Gradient descent.}} 
Starting from some initial point $x_0 \in \mathbb{R}^d$, we consider $N$ iterations of gradient descent with fixed stepsizes $\gamma_i \in (0, \tfrac{2}{L})$, defined as:
\begin{align}\label{eq:GM_it_fixed_steps}\tag{GD}
    x_{i+1} = x_i - \gamma_i \nabla f(x_i), \quad \forall i = 0,\dots,N-1.
\end{align}

\begin{definition}\label{def:def_TN}% 
Let $k$ be a positive integer and define function $E_k:\mathbb{R}\backslash\{0\} \rightarrow \mathbb{R}$:%
\begin{align}
    \Ei{}{}\coloneqq{}{}\sum\limits_{j=1}^{2k} x^{-j} 
        {}={} 
     \left\{
    \arraycolsep=6pt
    \def\arraystretch{1.25}
    \begin{array}{cc}
      \frac{-1+x^{-2k}}{1-x}, & x \neq 1; \\
      2k, & x = 1.
    \end{array}
    \right. \label{eq:def_Ei} \tag{$E_k$}
\end{align}%
Let $V \coloneqq \{(\ell, \kappa): \, \kappa \in (-\infty, 1), \,\ell \in (1, \frac{2}{1+[\kappa]_{+}})\}$ and define $T_k: V \rightarrow \mathbb{R}$ as %
\begin{align}
    T_k(\ell,\kappa)
        {}{}\coloneqq{}{}&
    \Ei[k][1-\kappa \ell] - \Ei[k][1-\ell] \label{eq:def_TN} \tag{$T_k$}.
\end{align}
\end{definition}

\begin{definition}[Stepsize thresholds]\label{def:stepsize_thresholds}%
Let $\gbari[\infty]{}\coloneqq{} \frac{2}{1+[\kappa]_{+}}$. The unique roots of $\TigLmu$ in the interval $(1,\gbari[\infty])$ are referred to as stepsize thresholds and denoted by $\gbari[k]$, where $\gbari[0] {}{}\coloneqq{}{} 1$ and:%
\begin{align}\label{def:gamma_bar} \tag{$\xoverline{\gamma L}_k$}
    \big\{\gbari[k]\big\} 
        {}{}\coloneqq{}{} 
    \big\{ \gamma L \in (1,\gbari[\infty]) \,|\, \TigLmu[k] = 0 \big\} {}\quad{} \forall k = 1,2,{\dots}\,\,.%
\end{align}%
\end{definition}

\paragraph*{	extbf{Additional notation. }}\, For brevity, we sometimes use $
{=}
(\gamma L){}{\coloneqq}{}1{-}\gamma L \in (-1, 0)$, $\m{=}\m(\gamma \mu){}{\coloneqq}{}1{-}\gamma \mu$. Then $T_k(\gamma L, \kappa) = E_k(1{-}\kappa \gamma L) {-} E_k(1{-}\gamma L)$ (see \cref{def:def_TN}), where
$E_k(x) = \sum_{j=1}^{2k} x^{-j}$, can be equivalently written as $\Tinm{}\coloneqq{}\TigLmu$, with $\Tinm=\Ei[k][\m]-\Ei[k][
]$. Recall $\gbari[\infty] =  rac{2}{1+[\kappa]_{+}}$.%

\begin{definition}\label{def:N_bar}
Let $\Nbar
        {}{}\coloneqq{}{}
    \max \{ k \in \mathbb{N} \,|\, \TigLmu[k] {}\geq{} 0\}$.
\end{definition}

Interpolation conditions are used in conjunction with the  \eqref{eq:GM_it_fixed_steps} iterations by substituting $x_{j}=x_{i} - \sum_{k=i}^{j-1} \gamma_k \nabla f(x_k)$, as detailed in \cref{def:dist-N_interp_cond}. Since the proofs are limited to constant stepsizes, we constrain $\gamma_k$ to $\gamma$.%
\begin{definition}\label{def:dist-N_interp_cond}
Inequalities \eqref{eq:distance-N_interpolation_conditions_I_ij} and \eqref{eq:distance-N_interpolation_conditions_I_ji} are necessary and sufficient conditions connecting gradient descent iterations separated by $(j-i)$ steps:
% %%%%%%%%%%%%%%%%%%%%%%% Improved decent version %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{align}\label{eq:distance-N_interpolation_conditions_I_ij}
    & \hspace{-.75em}
    \begin{aligned}
    f(x_{i})-f(x_{j})
        {}\geq {}  
    \gamma \big \langle \nabla f(x_{j}), \sSum_{k=i}^{j-1} \nabla f(x_{k}) \big \rangle +
    \frac{1}{2L} \left\|\nabla f(x_{i}) - \nabla f(x_{j})\right\|^2 + 
    \\% {}\qquad{}
    \frac{\mu}{2L(L{-}\mu)} \big\|\nabla f(x_{i}) - \nabla f(x_{j}) - \gamma L \sSum_{k=i}^{j-1} \nabla f(x_{k})\big\|^2; 
    \end{aligned} \tag{$\Iij$} \\
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    & \hspace{-.75em}
    \begin{aligned} 
    f(x_{j})-f(x_{i}) 
        {}\geq {}
    {-}\gamma \big \langle \nabla f(x_{i}), \sSum_{k=i}^{j-1} \nabla f(x_{k}) \big \rangle +
    \frac{1}{2L} \left\|\nabla f(x_{i}) - \nabla f(x_{j})\right\|^2 + 
    \\% {}\qquad{}
    \frac{\mu}{2L(L{-}\mu)} \big\|\nabla f(x_{i}) - \nabla f(x_{j}) - \gamma L \sSum_{k=i}^{j-1} \nabla f(x_{k})\big\|^2.
    \end{aligned} \tag{$\Iji$}
    \label{eq:distance-N_interpolation_conditions_I_ji}
\end{align}%
We refer to inequalities \eqref{eq:distance-N_interpolation_conditions_I_ij} and \eqref{eq:distance-N_interpolation_conditions_I_ji} as \textit{distance-1} or \textit{distance-2} inequalities if the distances between their indices satisfy $|i-j|\leq 1$ or $|i-j|\leq 2$, respectively.%
\end{definition}

Inequalities \eqref{eq:distance-N_interpolation_conditions_I_ij} and \eqref{eq:distance-N_interpolation_conditions_I_ji} contribute via nonnegative weights 
$\alphaij[i][j]$ and $\alphaij[j][i]$, respectively, to form a generalized inequality linking $N$ iterations\footnote{For linear combination of inequalities, we adopt the convention of writing the summed expression on the left-hand side, while stating the corresponding inequalities explicitly on the right-hand side.} such that there exists nonnegative weights $\sigma_i \geq 0$ satisfying:%
\begin{align}\label{eq:I^k_N_general_ineq}\tag{\ENQ}
\sum_{0\leq i < j \leq N} \big(\alphaij[i][j] \Iij[i][j] + \alphaij[j][i] \Iij[j][i]\big)\colon \,\,
    f(x_0) - f(x_N) {}\geq{}  \sum_{i=0}^N \sigma_i \frac{\|\nabla f(x_i)\|^2}{2L}.%
\end{align}

For $|j-i|=1$, inequalities \eqref{eq:distance-N_interpolation_conditions_I_ij} and \eqref{eq:distance-N_interpolation_conditions_I_ji} simplify to:%
\begin{align} 
% \hspace{-.75em}
    f_{i}{-}f_{i+1}
        {}\geq {} &
    \frac{\gamma \mu \, \gamma L {-} 2 \gamma \mu {+} 1}{L{-}\mu} \frac{\|g_{i}\|^2}{2} +
    \frac{1}{L{-}\mu} \frac{\|g_{i+1}\|^{2}}{2} +     
    \frac{\gamma L{-}1}{L{-}\mu} \langle g_{i}, g_{i+1}\rangle; 
\label{eq:hypo_interp_(0,1)} \tag{\Iij[i][i+1]}\\
    %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
% \hspace{-1em}
    f_{i+1}{-}f_{i}
        {}\geq {} &
    \frac{\gamma \mu \gamma L {-} 2 \gamma L {+} 1}{L-\mu} \frac{\|g_{i}\|^2}{2} +
    \frac{1}{L{-}\mu} \frac{\|g_{i+1}\|^{2}}{2} +     
    \frac{\gamma \mu {-} 1}{L{-}\mu} \langle g_{i}, g_{i+1}\rangle.
\label{eq:hypo_interp_(1,0)} \tag{\Iji[i][i+1]}
\end{align}

\begin{definition}
    We use the writing $\TigLmu[k][\gamma L] {}={} \sum_{i=1}^k \delta_i(\gamma L, \kappa)$, where
    $$
        \delta_i(\gamma L,\kappa) 
            {}{}\coloneqq{}{} 
        \frac{2-\kappa \gamma L}{(1-\kappa \gamma L)^{2i}} - 
        \frac{2-\gamma L}{(1-\gamma L)^{2i}}.
    $$ 
\end{definition}

\begin{proposition}\label{prop:monotonicity_Tk}%
    The function $\TigLmu[k][\cdot][\kappa]$ is strictly increasing in the first argument.%
\end{proposition}

\begin{proof}%
See \cref{appendix:proof_prop_monotonicity_Tk}.%
\qed\end{proof}

\begin{proof}[\textbf{\cref{prop:monotonicity_Tk}}] \label{appendix:proof_prop_monotonicity_Tk}
We show $\frac{d\TigLmu}{d (\gamma L)} \geq 0$ for $\gamma L \in (1, \gbari[\infty])$, which resumes to prove the positivity of
  \begin{align*}
        \frac{d \delta_i(\gamma L, \kappa)}{d(\gamma L)}
            {}{}\coloneqq{}{}
      \frac{-\kappa \left( 1 - 2i \frac{2-\kappa \gamma L}{1-\kappa \gamma L} \right) }{(1-\kappa \gamma L)^{2i}} + \frac{ 1 + 2i \frac{2-\gamma L}{\gamma L-1}}{(1-\gamma L)^{2i}}.
  \end{align*}
  \begin{enumerate}[align=right,itemindent=1em,labelsep=2pt,labelwidth=1em,leftmargin=0pt,nosep]
      \item \textbf{Case $\kappa \geq 0$:} we lower bound $\frac{d \delta_i(\gamma L, \kappa)}{d(\gamma L)}$ by neglecting the denominators:
      \begin{align*}
          \delta_i(\gamma L, \kappa) 
            {}\geq{} 
          {-}\kappa \Big( 1 - 2i \frac{2-\kappa \gamma L}{1-\kappa \gamma L} \Big) + 1 + 2i \frac{2-\gamma L}{\gamma L-1}
            {}={}
          (1-\kappa) + 2i \Big[ \frac{\kappa (2-\kappa \gamma L)}{1-\kappa \gamma L}  + \frac{2-\gamma L}{\gamma L-1} \Big] {}\geq{} 0.
      \end{align*}%
        %
      \item \textbf{Case $\kappa < 0$:} it is sufficient to show 
    \begin{align*}
        \frac{1+2i \frac{2-\gamma L}{\gamma L -1}}{(1-\gamma L)^{2i}}
            {}\geq{} 1 {}\geq{}
        -\kappa \frac{-1+2i (1 + \frac{1}{1-\kappa \gamma L})}{(1-\kappa \gamma L)^{2i}}.
    \end{align*}
      The \lhs holds because $\gamma L \in (1,2)$ and $(1-\gamma L)^{2i}<1$. The \rhs is equivalent to:%
      \begin{align*}
          (1-\kappa \gamma L)^{2i} {}\geq{} -\kappa \Big[-1+2i \Big(1 + \frac{1}{1-\kappa \gamma L}\Big)\Big].
      \end{align*}
Using $\gamma L \in (1,2)$ and the second order Taylor approximation for $(1-\kappa)^{2i}$, we get the bounds:%
      \begin{align*}
          (1-\kappa \gamma L)^{2i} {}\geq{}& (1-\kappa)^{2i} 
             {}\geq{} 
         1 + 2i (-\kappa) + i(2i-1) \kappa^2 \\
         %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
          -\kappa \Big[-1+2i \Big(1 + \frac{1}{1-\kappa \gamma L}\Big)\Big]
            {}\leq{}&
          -\kappa \Big[-1+2i \left(1 + \frac{1}{1-\kappa}\right)\Big].
      \end{align*}
Therefore, it is sufficient to show:%
$$
    1 + 2i (-\kappa) + i(2i-1) \kappa^2 {}\geq{} 
    -\kappa \Big[-1+2i \Big(1 + \frac{1}{1-\kappa}\Big)\Big],%
$$%
which equivalently rewrites as the following inequality valid for all $i \geq 1$:
$$
    \kappa^2 i(i-1) + \Big( \kappa i + \frac{1}{1-\kappa} \Big)^2 + \frac{(1-\kappa)^3-1}{(1-\kappa)^2} \geq 0. {}\qquad \qed{}%
$$%
\end{enumerate}
\end{proof}

