\begin{proposition}\label{prop:properties_step_size_thr}
    The stepsize thresholds $\gbari$ satisfy the following properties:%
    \begin{enumerate}[align=right,itemindent=1em,labelsep=2pt,labelwidth=1em,leftmargin=0pt,nosep]
        \item $\gbari[k] < \gbari[k+1]$, for all integers $k \geq 0$;
        \item $\lim_{k\rightarrow \infty} \gbari[k] = \gbari[\infty]$;
        \item \shownewtextfinal{For any $\gamma L \in \big[\gbari[k],\gbari[k+1]\big)$: 
        $\TigLmu[i][\gamma L] \geq 0$ $\forall i \leq k$, 
        and $\TigLmu[i][\gamma L] < 0$ $\forall i \geq k+1$.}
     \end{enumerate}%
\end{proposition}

\begin{proof}%
See \cref{appendix:proof_properties_step_size_thr}.%
\qed\end{proof}

\begin{proof}[\textbf{\cref{prop:properties_step_size_thr}}] \label{appendix:proof_properties_step_size_thr} 
\begin{enumerate}[align=right,itemindent=1em,labelsep=2pt,labelwidth=1em,leftmargin=0pt,nosep]
\item Case $k=0$ holds by definition since $\gbari[0]=1$. For any $k \geq 1$, by using \cref{lemma:unique_delta_k_neg_thr}, condition $\TigLmu[k][\gbari[k][]] = 0$ implies $\delta_k(\gamma L, \kappa) \leq 0$ and hence $\delta_{k+1}(\gamma L, \kappa) < 0$. Furthermore, $\TigLmu[k+1][\gbari[k][]] {} \leq {} \TigLmu[k][\gbari[k][]] = 0$. Then it holds:
\begin{align*}
    \TigLmu[k+1][\gbari[k][]] {} \leq {} 
    \TigLmu[k][\gbari[k][]] = 0 
    {}={} \TigLmu[k+1][\gbari[k+1][]].
\end{align*}
The monotonicity of $\TigLmu$ in stepsize $\gamma L$ (see \cref{prop:monotonicity_Tk}) implies $\gbari[k] < \gbari[k+1]$.

\item Because stepsize thresholds sequence is monotone, it has a limit.
\begin{enumerate}[align=right,itemindent=1.5em,labelsep=2pt,labelwidth=1em,leftmargin=0pt,nosep]
    %%%%%%%%%%%%%%%%%%%%%%%%%% 2. %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \item 
    \textbf{Case $\kappa > 0$.} By definition, $\gbari[k] < \frac{2}{1+\kappa} < 2$ for all integers $k\geq 1$ and condition $\TigLmu[k][\gbari[k]]=0$ implies:%
    \begin{align*}
        \left(\frac{1-\gbari}{1-\kappa \gbari}\right)^{2k}
            {}={}& 
        \kappa + (1-\kappa) (1-\gbari)^{2k}
            {}\Leftrightarrow{} \\
            %%%%%%%%%%%%%%%%%%%%%%%%%%%%
        \left|\frac{1-\gbari}{1-\kappa \gbari}\right|
            {}={}&
        \exp \left[ \frac{\ln \left(\kappa + (1-\kappa) (1-\gbari)^{2k}\right)}{2k} \right].
    \end{align*}%
    To the limit $k \rightarrow \infty$, the \rhs equals $1$ because $(1-\gbari)^{2k}\rightarrow 0$, hence $|1-\gbari|=|1-\kappa \gbari|$, which implies the solution $\gbari[\infty]=\frac{2}{1+\kappa}$. \\
    %%%%%%%%%%%%%%%%%%%%%%%%%%
    \item \textbf{Case $\kappa < 0$.} By definition, $\gbari < 2$ for all integers $k\geq 1$ and condition $\TigLmu[k][\gbari[k]]=0$ implies:
    \begin{align*}
    (1-\gbari)^{-2k} 
        {}={}&
    1 + \frac{1 - (1-\kappa \gbari)^{-2k}}{-\kappa}
        {}\Leftrightarrow{} \\
    % %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    \left|1-\gbari\right| 
        {}={}&
    \exp \Bigg[ \frac{ -\ln \Big(1 + \frac{1 - (1-\kappa \gbari)^{-2k}}{-\kappa}\Big)}{2k} \Bigg].
\end{align*}
 To the limit $k \rightarrow \infty$, the \rhs equals $1$ because $(1-\kappa \gbari)^{-2k} \rightarrow 0$ due to $\kappa < 0$. Hence, $\left|1-\gbari\right|=1$, with the solution $\gbari[\infty]=2$.%
 %
\item \textbf{Case $\kappa = 0$.} By definition, $\gbari[k][(0)] < 2$ and, similarly to the case $\kappa < 0$:%
 \begin{align*}
     \left|1-\gbari\right|
        {}={}&
     \left[ 1 + 2 k \gbari \right]^{\frac{-1}{2k}}
        {}={}
    \exp \Big[ \frac{-\ln \big( 1 + 2 k \gbari \big) }{2k} \Big].
 \end{align*}
  To the limit $k \rightarrow \infty$, the \rhs equals $1$, hence $\left|1-\gbari\right|=1$, with the solution $\gbari[\infty]=2$.
\end{enumerate}%
%
\item Condition $\gamma L \in [\gbari[k], \gbari[k+1])$ implies $\TigLmu[k][\gbari[k]] \geq 0$ and $\TigLmu[k+1][\gbari[k]] < 0$. Because $\delta_i(\gamma L, \kappa) < 0$ for all $i \geq k$, we have (i) $\TigLmu[i][\gbari[k][]] {}>{} 0$ for $i=1,\dots,k-1$ (since $k$ is uniquely defined) and (ii) $\TigLmu[i][\gbari[k][]] {}<{} 0$ for $i\geq k+1$. {}\qed{}%
\end{enumerate}
\end{proof}

