\begin{theorem}[Interpolation conditions for smooth functions]\label{thm:interp_hypo}
Set $\mathcal{T}=\big\{(x_i, g_i, f_i)\big\}_{i \in \mathcal{I}}$ is $\mathcal{F}_{\mu,L}$-interpolable, where $\mu \in (-\infty, L)$, if and only if for every pair of indices $(i,j)$, with $i,j \in \mathcal{I}$, it holds:%
\begin{align}\label{eq:Interp_hypoconvex}
f_{i}{-}f_{j}{-}\langle g_{j}, x_{i}-x_{j} \rangle 
        {}\geq{}
    \frac{1}{2L} \|g_{i}{-}g_{j}\|^{2} {}+{} \frac{\mu}{2L(L{-}\mu)} \|g_{i}{-}g_{j} {-} L (x_i {-}x_j)\|^2.
\end{align}%
\end{theorem}

\begin{proof}[\textbf{\cref{thm:interp_hypo}}]%
    The proof follows the same steps outlined in \cite[Theorem 4]{taylor_smooth_2017}, with a minimal extension to accommodate $\mu < 0$. This extension impacts only the first step of the demonstration, known as minimal curvature subtraction, which involves shifting the lower curvature of the function to $0$, effectively converting it into a smooth convex function. This adjustment remains valid for $\mu < 0$, as showed further on. By applying the \textit{gradient inequality} for smooth convex functions: $h(x) {} \geq {} h(y) + \left \langle \nabla h(y), x-y \right \rangle, \, \forall x,y \in \mathbb{R}^d$ for $h = \frac{L}{2}\|\cdot\|^2-f$ and $h = f - \frac{\mu}{2}\|\cdot\|^2$, we obtain:%
    \begin{align}\label{eq:def_hypoconvex_smooth}
    \tfrac{\mu}{2} \|x-y\|^2 
        {} \leq {} 
    f(x) - f(y) - \langle \nabla f(y), x-y \rangle 
        {} \leq {} 
    \tfrac{L}{2} \|x-y\|^2 \quad \forall x, y \in \mathbb{R}^d.
\end{align}%

Hence, the set $\{(x_i, g_i, f_i)\}_{i \in \mathcal{I}}$ is $\mathcal{F}_{\mu,L}$-interpolable if and only if the set $\{(x_i, g_i-\mu x_i, f_i-\tfrac{\mu}{2}\|x_i\|^2)\}_{i \in \mathcal{I}}$ is $\mathcal{F}_{0, L-\mu}$-interpolable. 
Subsequently, the proof continues identically to \cite[Theorem 4]{taylor_smooth_2017}.
\qed\end{proof}

\begin{corollary} \label{corr:direct_sum_interp_cond} 
Let $f \in \mathcal{F}_{\mu,L}$, with $\mu \in (-\infty, L)$. For all $x_i, x_j \in \mathbb{R}^d$ it holds:%
\begin{align}\label{eq:direct_sum_interp_cond}
    0 {}\geq{} \left\langle \nabla f(x_i) - \nabla f(x_j) - L(x_i-x_j) \,,\, 
                           \nabla f(x_i) - \nabla f(x_j) - \mu(x_i-x_j) \right\rangle.
\end{align}%
\end{corollary}

\begin{proof}
    Inequality \eqref{eq:direct_sum_interp_cond} results by summing up inequalities \eqref{eq:Interp_hypoconvex} written for the pairs $(x_i,x_j)$ and $(x_j,x_i)$ and performing simplifications.
\qed\end{proof}

\begin{proof}
    Inequality \eqref{eq:direct_sum_interp_cond} results by summing up inequalities \eqref{eq:Interp_hypoconvex} written for the pairs $(x_i,x_j)$ and $(x_j,x_i)$ and performing simplifications.
\qed\end{proof}

