\begin{lemma}\label{lemma:general_lemma_ct_h_to_Linear_mu} 
Let $f \in \mathcal{F}_{\mu,L}$, with $\mu \in (-\infty,L)$, and consider $k+1 \geq 1$ iterations of \eqref{eq:GM_it_fixed_steps} with stepsize $\gamma L \in [\gbari[k], \gbari[\infty])$, satisfying $\gamma L > 1$, starting from $x_0$. Then the following inequality holds:%
\begin{align}\label{eq:general_ineq_proof_to_linear_mu_compact}
% \hspace{-.75em}
    \frac{f(x_0) {-} f(x_{k+1})}{\gamma}
        {\geq}
    \Ei[k+1][\m] \frac{\|\nabla f(x_{k+1})\|^2}{2} {+} 
    \frac{-\n^2 \Tinm[k+1]}{(\m{-}\n)^2}
    \frac{\| \nabla f(x_{k+1}) {-} \m \nabla f(x_{k}) \|^2}{2}.
\end{align}%
Furthermore, if $\gamma L \in [\gbari[k], \gbari[k+1] \big)$, then $\Tinm[k+1]<0$.
\end{lemma}

\begin{proof}
Case $k=0$ results from \cref{lemma:dist_1_mu_1_step_decrease}; further on, $k\geq 1$. Inequality \eqref{eq:direct_sum_interp_cond} written for the pair $(i,j)=(k,k+1)$ reads:%
   \begin{align}\label{eq:dist_1_correction_to_mu}
       0
        {}\geq{}
       \frac{\m \n}{\m-\n} \|g_{k}\|^2 + \frac{1}{\m-\n} \|g_{k+1}\|^2 - \frac{\m+\n}{\m-\n} \langle g_{k} \,,\, g_{k+1} \rangle.
   \end{align}%

By multiplying it with $\frac{-\n^2}{\m^2-\n^2}\Tinm[k+1]$ (positive because $\Tinm[k+1] < 0$) and adding it to \eqref{eq:general_ineq_proof}, the coefficient of $\|g_{k}\|^2$ is canceled and we get:%
 $$
 \frac{f_0{-}f_{k+1}}{\gamma}
     {}{\geq}{}
 \frac{\Tinm[k]{+}(\m{-}\n){-}\n^2 \Tinm[k+1]}{\m^2{-}\n^2} \frac{\|g_{k+1}\|^2}{2} {}+{}
    \frac{{-}\n^2 \Tinm[k+1]}{(\m{-}\n)^2}  \frac{\|g_{k+1}{-}\m g_{k}\|^2}{2},
 $$
 which after simplifications is exactly \eqref{eq:general_ineq_proof_to_linear_mu_compact}.%
